#!/usr/bin/env node
// Read-only check of a PUBLICLY REACHABLE Vercel review copy: every application response must carry the security headers and
// the review-copy `X-Robots-Tag: noindex, nofollow` defined in vercel.json (generated by scripts/vercel-config.js).
//
//   node scripts/check-vercel-deployment.js https://<name>.vercel.app
//
// What it does: plain GET requests to ten fixed URLs of the address you pass, with redirects NOT followed and nothing extra sent
// (no cookies, tokens, bypass secrets, environment variables or Vercel settings are read, used or created).
// What it cannot do: verify a deployment that sits behind Vercel Authentication / password protection. A login redirect (or 401)
// is reported as "protected; application headers remain unverified" and is neither a pass nor a header failure. Do NOT work around
// that with `vercel curl`: on a protected deployment it can create a project-level "Protection Bypass for Automation" secret.
// It refuses anything that is not an https *.vercel.app address: the real website (sfrmotors.co.uk on its production hosting)
// must NEVER send noindex.
//
// Exit codes: 0 all headers present; 1 headers missing/different or unexpected response; 2 usage error or refused address;
//             3 deployment protected, application headers unverified.

"use strict";

const { buildConfig } = require("./vercel-config");

const PROTECTED_MESSAGE = "Deployment is protected; application headers remain unverified.";
const FIXED_PATHS = ["/", "/about-us/", "/contact-us/", "/services.html", "/privacy-policy.html", "/robots.txt", "/sitemap.xml", "/favicon.ico", "/does-not-exist/"];
// The tenth URL is the content-hashed stylesheet named in the Home page.
const CSS_PATTERN = /href="?\/?(assets\/css\/main\.[0-9a-f]+\.css)/;

function parseReviewCopyUrl(input) {
  let url;
  try { url = new URL(input); } catch { return null; }
  const host = url.hostname;
  const ok = url.protocol === "https:" && !url.username && !url.password && !url.port && host.endsWith(".vercel.app") && host.length > ".vercel.app".length && /^[a-z0-9.-]+$/.test(host);
  return ok ? url.origin : null;
}

// A login/SSO redirect (to vercel.com) or a 401 means Vercel Authentication or a password is in front of the site.
function isProtectionResponse(res, origin) {
  if (res.status === 401) return true;
  if (res.status >= 300 && res.status < 400) {
    let target;
    try { target = new URL(res.headers.get("location") || "", origin); } catch { return false; }
    return target.hostname === "vercel.com" || target.hostname.endsWith(".vercel.com");
  }
  return false;
}

// Returns { outcome: "ok" | "failed" | "protected" | "refused", urls, checks, problems, message }.
async function checkDeployment(input, { fetchFn = fetch } = {}) {
  const origin = parseReviewCopyUrl(input);
  if (!origin) return { outcome: "refused", urls: [], checks: 0, problems: [], message: "Only https://<name>.vercel.app review copies are accepted (never the real website or a custom domain)." };

  const expected = buildConfig().headers.find((rule) => rule.source === "/(.*)").headers;
  const get = (p) => fetchFn(origin + p, { method: "GET", redirect: "manual", headers: { "accept-encoding": "identity" } });
  const protectedResult = (urls) => ({ outcome: "protected", urls, checks: 0, problems: [], message: PROTECTED_MESSAGE });

  const home = await get("/");
  if (isProtectionResponse(home, origin)) return protectedResult(["/"]);
  const css = (((await home.text()).match(CSS_PATTERN)) || [])[1];
  const paths = [...FIXED_PATHS, css && "/" + css].filter(Boolean);

  const problems = [];
  let checks = 0;
  for (const p of paths) {
    const res = p === "/" ? home : await get(p);
    if (isProtectionResponse(res, origin)) return protectedResult(paths);
    const wantStatus = p === "/does-not-exist/" ? 404 : 200;
    if (res.status !== wantStatus) { problems.push(`${p}: status ${res.status}, expected ${wantStatus}${res.status >= 300 && res.status < 400 ? " (redirects are not followed)" : ""}`); continue; }
    for (const { key, value } of expected) {
      checks++;
      const actual = res.headers.get(key);
      if (actual !== value) problems.push(`${p} (${res.status}): ${key} is ${actual === null ? "MISSING" : `"${actual}"`}, expected "${value}"`);
    }
  }
  return { outcome: problems.length ? "failed" : "ok", urls: paths, checks, problems, message: "" };
}

module.exports = { checkDeployment, parseReviewCopyUrl, FIXED_PATHS, PROTECTED_MESSAGE };

if (require.main === module) {
  checkDeployment(process.argv[2] || "").then((r) => {
    if (r.outcome === "refused") { console.error("Usage: node scripts/check-vercel-deployment.js https://<name>.vercel.app\n" + r.message); process.exit(2); }
    if (r.outcome === "protected") { console.log(PROTECTED_MESSAGE); console.log("No headers were compared, so this is neither a pass nor a failure. Nothing was bypassed."); process.exit(3); }
    console.log(`${process.argv[2]}: ${r.checks} header checks over ${r.urls.length} URLs`);
    if (r.outcome === "failed") { r.problems.forEach((p) => console.error("FAIL " + p)); process.exit(1); }
    console.log("Deployed responses carry every required header, including X-Robots-Tag: noindex, nofollow");
  }).catch((e) => { console.error(e); process.exit(2); });
}
